    "OPENCLAW_TEST_WORKERS",
    "OPENCLAW_VITEST_SHARD_NAME",
    "OPENCLAW_NODE_TEST_VITEST_ARGS_JSON",
    "OPENCLAW_VITEST_NO_OUTPUT_TIMEOUT_MS",
    "OPENCLAW_VITEST_NO_OUTPUT_HEARTBEAT_MS",
  ]);
