    }
    if (key === "RAYON_NUM_THREADS" || key === "TOKIO_WORKER_THREADS") {
      const limits = values.filter((value) => value?.trim()).map(parsePositiveInt);
      if (limits.every((limit) => limit !== null)) {
        if (limits.length > 0) {
          shared[key] = String(Math.min(...limits));
        } else {
